// Mock interview timer and constraint setup
public class MockInterviewSession {
    private final Duration timeLimit = Duration.ofMinutes(45);
    private final boolean allowIDE = false; // Force whiteboard or doc
    private final boolean allowSearch = false; // No Google during session

    public void conductMockInterview(Problem problem) {
        var startTime = Instant.now();
        System.out.println("Problem: " + problem.description());
        System.out.println("Time starts now. Explain your approach first.");

        // Simulate interviewer waiting for verbal explanation
        waitForVerbalApproach();

        // Candidate codes in shared doc, not IDE
        var solution = candidateWritesSolution(problem);

        var elapsed = Duration.between(startTime, Instant.now());
        if (elapsed.compareTo(timeLimit) > 0) {
            System.out.println("Time exceeded. Let's review what you have.");
        }

        // Post-interview review: what went well, what to improve
        reviewSession(solution, elapsed);
    }
}

// Setup for realistic interview simulation
public class InterviewSimulation {

    record SessionConfig(
        Duration timeLimit,
        boolean ideAllowed,
        boolean googleAllowed,
        boolean requireVerbalExplanation
    ) {}

    public static SessionConfig getRealConditions() {
        return new SessionConfig(
            Duration.ofMinutes(45),
            false, // Use whiteboard or plain text doc only
            false, // No search engines during problem
            true   // Must explain approach out loud before coding
        );
    }

    public void runPracticeSession(Problem problem, SessionConfig config) {
        var timer = new Timer();
        timer.schedule(new TimerTask() {
            public void run() {
                System.out.println("Time's up! Stop coding now.");
            }
        }, config.timeLimit().toMillis());

        System.out.println("Problem: " + problem.description());
        System.out.println("Explain your approach verbally first.");
        // Force verbal explanation before writing any code
    }
}

// STAR story structure as a data model
record STARStory(
    String situation,  // Context: 1-2 sentences, what was happening
    String task,       // Your responsibility: what you needed to accomplish
    String action,     // What you did: 3-5 specific steps you took
    String result      // Measurable outcome: how did it improve things
) {}

// Example: debugging a production issue
var debuggingStory = new STARStory(
    "During my internship, our user service started throwing 500 errors at 10% request rate in production after a Friday deployment.",

    "As the intern who wrote that deployment's API changes, I was asked to investigate and fix the issue urgently before Monday.",

    "I pulled production logs, found NullPointerExceptions in the new code path, traced it to missing validation on optional fields, wrote a hotfix with proper null checks, tested locally with edge cases, and deployed the fix Saturday morning.",

    "Error rate dropped to 0.1% within an hour. I documented the incident in our wiki and added integration tests to catch null-handling bugs before production."
);

// Map stories to common interview themes
var storyInventory = Map.of(
    "Challenge", debuggingStory,
    "Failure", anotherStory,
    "Initiative", yetAnotherStory
);

// Two-pointer pattern: Container With Most Water (LeetCode 11)
public class TwoPointerExample {

    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;
        int maxArea = 0;

        // Classic two-pointer: move pointers toward center
        while (left < right) {
            int width = right - left;
            int currentHeight = Math.min(height[left], height[right]);
            int area = width * currentHeight;
            maxArea = Math.max(maxArea, area);

            // Move pointer at shorter line (greedy choice)
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maxArea;
    }
}
